"""Post-processes UI kit v2 art generated by tools/ui/generate_ui_kit_v2.ps1.

Raw PixelLab outputs are kept in docs/design/ui/kit-v2/raw/<id>.png; processed files go to
apps/client/public/assets/ui/v2/<id>.png. Frames whose hollow centre came back as an opaque light fill get that fill
cleared by a flood fill from the centre (only light pixels connected to the centre are touched), so the CSS interior
shows through. Prints each frame's opaque bounding box and cleared pixel count.
Usage: python -I tools/ui/build_kit_v2.py
"""
from collections import deque
from pathlib import Path
from PIL import Image

ROOT = Path(__file__).resolve().parents[2]
RAW = ROOT / 'docs/design/ui/kit-v2/raw'
OUT = ROOT / 'apps/client/public/assets/ui/v2'
HOLLOW = ['frame/window', 'frame/skill', 'frame/portrait', 'frame/button', 'frame/field', 'frame/plate', 'frame/iconbutton', 'frame/bar']


def light(p, limit=200):
    r, g, b, a = p
    return a > 0 and min(r, g, b) >= limit


def clear_centre(img: Image.Image, seeds) -> int:
    px = img.load()
    w, h = img.size
    queue = deque(s for s in seeds if light(px[s]) or px[s][3] == 0)
    seen = set(queue)
    cleared = 0
    while queue:
        x, y = queue.popleft()
        if px[x, y][3] != 0:
            px[x, y] = (0, 0, 0, 0)
            cleared += 1
        for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
            if 0 <= nx < w and 0 <= ny < h and (nx, ny) not in seen and (light(px[nx, ny]) or px[nx, ny][3] == 0):
                seen.add((nx, ny))
                queue.append((nx, ny))
    return cleared


for src in sorted(RAW.rglob('*.png')):
    rel = src.relative_to(RAW).with_suffix('').as_posix()
    img = Image.open(src).convert('RGBA')
    note = ''
    if rel in HOLLOW:
        w, h = img.size
        # Seed a small cross around the centre (the portrait window sits a little above centre).
        cx, cy = w // 2, h // 2
        seeds = [(cx + dx, cy + dy) for dx in range(-3, 4) for dy in range(-8, 4)]
        note = f' cleared {clear_centre(img, seeds)} px'
    dst = OUT / f'{rel}.png'
    dst.parent.mkdir(parents=True, exist_ok=True)
    img.save(dst)
    print(f'{rel}: {img.size} bbox {img.getbbox()}{note}')


# Window 9-slice source: the generated frame has one medallion in the middle of its top edge. Repeating that edge
# would print a medallion every tile, so the top middle is rebuilt from the left kanok carving and its mirror, and the
# medallion is cut out as its own ornament (placed once, centred, by CSS).
# Slices (source px, measured on the band): top 80 (keeps the corner cloth), right 35, bottom 41, left 34.
SLICE = {'top': 80, 'right': 35, 'bottom': 41, 'left': 34}
win = Image.open(OUT / 'frame/window.png').convert('RGBA')
W, H = win.size
mid_l, mid_r = SLICE['left'], W - SLICE['right']          # top edge middle: x 34..156
# Medallion = bronze disc centred (96.5, 37) r 12.5 plus its hanging ring centred (96.5, 21) r 4.8 (read off an 8x
# zoom); everything else in its box is the wooden band behind it and is dropped.
medal = Image.new('RGBA', (W, H), (0, 0, 0, 0))
wpx, mpx = win.load(), medal.load()
for y in range(8, 52):
    for x in range(80, 114):
        if ((x + 0.5 - 96.5) ** 2 + (y + 0.5 - 37) ** 2) ** 0.5 <= 12.5 or ((x + 0.5 - 96.5) ** 2 + (y + 0.5 - 21) ** 2) ** 0.5 <= 4.8:
            mpx[x, y] = wpx[x, y]
(OUT / 'ornament').mkdir(parents=True, exist_ok=True)
medal = medal.crop(medal.getbbox())
medal.save(OUT / 'ornament/medallion.png')
band = win.crop((mid_l, 0, mid_l + 46, SLICE['top']))      # left carving between the corner and the medallion
mirror = band.transpose(Image.Transpose.FLIP_LEFT_RIGHT)
filler_w = (mid_r - mid_l) - 2 * band.width
plain = win.crop((mid_l + 44, 0, mid_l + 45, SLICE['top'])).resize((max(0, filler_w), SLICE['top']), Image.NEAREST)
top = Image.new('RGBA', (mid_r - mid_l, SLICE['top']), (0, 0, 0, 0))
top.alpha_composite(band, (0, 0))
if filler_w > 0:
    top.alpha_composite(plain, (band.width, 0))
top.alpha_composite(mirror, (band.width + max(0, filler_w), 0))
nine = win.copy()
nine.paste((0, 0, 0, 0), (mid_l, 0, mid_r, SLICE['top']))
nine.alpha_composite(top, (mid_l, 0))
nine.save(OUT / 'frame/window-9s.png')
print('window 9-slice: slices', SLICE, 'medallion', medal.size, 'filler', filler_w)

# Item slot: the generated slot (48 px canvas) is a 27x31 frame with gems poking out top and bottom. The square
# 27x27 middle is used, drawn at 2x (54 px) so its 16 px opening fits a 32 px item icon.
slot = Image.open(OUT / 'frame/slot.png').convert('RGBA').crop((10, 9, 37, 36))
slot.save(OUT / 'frame/slot-square.png')
# Portrait arch cropped to its art (62x94); the opening is x 13..46, y 29..83 inside the crop.
portrait = Image.open(OUT / 'frame/portrait.png').convert('RGBA')
portrait.crop((14, 0, 76, 94)).save(OUT / 'frame/portrait-crop.png')
print('slot-square', slot.size, 'portrait-crop', (62, 94))


def nine_slice(name, crop, slices, plain_x=None, plain_y=None):
    """Writes frame/<name>-9s.png: the art cropped to `crop`, with the middle of the top/bottom edges replaced by
    copies of column `plain_x` and the middle of the left/right edges by copies of row `plain_y` (crop coordinates),
    so a centre gem is not repeated when the edges tile. `slices` = (top, right, bottom, left)."""
    img = Image.open(OUT / f'frame/{name}.png').convert('RGBA').crop(crop)
    w, h = img.size
    t, r, b, l = slices
    px = img.load()
    if plain_x is not None:
        for x in range(l, w - r):
            for y in list(range(0, t)) + list(range(h - b, h)):
                px[x, y] = px[plain_x, y]
    if plain_y is not None:
        for y in range(t, h - b):
            for x in list(range(0, l)) + list(range(w - r, w)):
                px[x, y] = px[x, plain_y]
    img.save(OUT / f'frame/{name}-9s.png')
    print(f'{name}-9s {img.size} slices {slices}')


# Measured on 6x zooms (see docs/design/ui-system.md, kit v2 full set).
nine_slice('button', (0, 0, 96, 32), (9, 16, 9, 16))
nine_slice('field', (0, 0, 96, 32), (8, 8, 8, 8), plain_x=24, plain_y=8)
nine_slice('bar', (0, 0, 128, 14), (3, 25, 5, 25))
nine_slice('plate', (0, 0, 96, 32), (10, 17, 10, 16), plain_x=24)
nine_slice('iconbutton', (0, 0, 40, 40), (11, 11, 11, 11), plain_x=12, plain_y=12)

